/// <summary>
/// Delete custQuotationJour record if  SendMode is Proforma
/// </summary>
public void avaDeleteProforma()
{
    if (custQuotationJour.KCS_SendMode == KCS_SendMode::Proforma)
    {
        custQuotationJour.delete();
    }
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_sender">SrsReportRunController</param>
/// <param name = "_eventArgs">SrsRenderingCompletedEventArgs</param>
public static void renderingCompleted(SrsReportRunController _sender, SrsRenderingCompletedEventArgs _eventArgs)
{
    if (classIdGet(_sender.parmArgs().caller()) == classNum(  SalesQuotationEditLinesForm_Sales_Send))
    {
        // from the sender get the underyling SalesConfirmJournalPrint instance
        SalesQuotationEditLinesForm_Sales_Send callerSales = _sender.parmArgs().caller();

        if (callerSales)
        {
            callerSales.avaDeleteProforma();
        }
    }
}

/// <summary>
/// designed by AVANADE
/// </summary>
protected void writeJournalLine()
{
    if (this.parmPrintWeights())
    {
        custQuotationTrans.KCS_GrossWeightME          = custQuotationTrans.AVAsetWeightPE(salesQuotationLine);
        custQuotationTrans.KCS_GrossWeightTotal       = custQuotationTrans.AVAsetWeightTotal(salesQuotationLine, custQuotationTrans.KCS_GrossWeightME);
    }

    next writeJournalLine();
}

/// <summary>
/// designed from AVA
/// </summary>
protected void writeJournal()
{
    AVASpecialDiscQuotationJour         specialDiscQuotationJour;
    //CustQuotationTrans                  custQuotationTrans;
    AmountMST                           quotLineAmount;
    AmountCur                           locQuotationBaseAmount;
    custQuotationJour                   locJour;
    //salesQuotationTable                 salesQuotationTable;
    DocuRef                             docuRef;
    DocuTypeId                          GAEBDocuTypeId;

    next writeJournal();

    this.avaDocuRefQuickCopy();

    GAEBDocuTypeId  = smmParametersTable::find().KCS_DocuTypeIdForGAEB;

    delete_from docuRef where docuRef.RefTableId == tableNum(CustQuotationJour)
                                      && docuRef.RefRecId == custQuotationJour.RecId
                                      && docuRef.TypeId == GAEBDocuTypeId;

    specialDiscQuotationJour.initFromQuotationJour(this.custQuotationJour, this.salesQuotationTable().QuotationId);
    specialDiscQuotationJour.insert();
    /* no simple sum up of LineAmount
    select sum(LineAmount)  from custQuotationTrans
        where   custQuotationTrans.QuotationId      == custQuotationJour.QuotationId
            &&  custQuotationTrans.QuotationDate    == custQuotationJour.QuotationDate
            &&  custQuotationTrans.SalesId          == custQuotationJour.SalesId;
    quotLineAmount = custQuotationTrans.LineAmount;
    */
    locQuotationBaseAmount = custQuotationJour.displayAVABaseAmount(false);

    locJour = custQuotationJour;
    this.parmCustQuotationJourRecId(custQuotationJour.RecId);
    locJour.selectForUpdate();
    //quotLineAmount = quotLineAmount - specialDiscQuotationJour.SpecialDiscountAmount1 - specialDiscQuotationJour.SpecialDiscountAmount2 - specialDiscQuotationJour.SpecialDiscountAmount3;
    quotLineAmount = locQuotationBaseAmount - specialDiscQuotationJour.displaySpecialDiscountAmountSum();
    locJour.KCS_QuotationAmount = quotLineAmount;
    locJour.KCS_SendMode        = this.parmSendMode();
    locJour.KCS_printWeights    = this.parmPrintWeights();
    if (locjour.kcs_printWeights)
    {
        locJour.KCS_TotalWeight = locJour.AVAsetWeightTotal(this.salesQuotationTable());
    }

    //locJour.AVAQuotationMatValue = this.avaCalcQuotationMatValue(custQuotationJour.QuotationId, custQuotationJour.QuotationDate);
    locJour.AVAQuotationMatValue = locQuotationBaseAmount;

    locJour.doUpdate();
    //select firstonly forupdate salesQuotationTable where salesQuotationTable.QuotationId == locJour.KCS_QuotationId;

   // this.salesQuotationTable(salesQuotationTable);
}

/// <summary>
/// AVA/WEN/2025/08/20   AVA_013264_SalesQuotationProforma_DocuRef
/// </summary>
public void avaDocuRefQuickCopy()
{
    DocuRef                 docuRef;
    DocuRef                 copyDocuRef;
    RecordInsertList        docuRefInsertList = new RecordInsertList(tableNum(DocuRef));
    CustQuotationTrans      locCustQuotationTrans;
    SalesQuotationLine      locSalesQuotationLine;

    delete_from docuRef where docuRef.RefTableId == tableNum(CustQuotationJour)
        && docuRef.RefRecId == custQuotationJour.RecId;
    while select locCustQuotationTrans
                       where locCustQuotationTrans.QuotationId   == custQuotationJour.QuotationId
                       && locCustQuotationTrans.QuotationDate == custQuotationJour.QuotationDate
    {
        delete_from docuRef where docuRef.RefTableId == tableNum(CustQuotationTrans)
        && docuRef.RefRecId == locCustQuotationTrans.RecId;
    }

    while select docuRef order by KCS_TCVLineNum
        where docuRef.RefTableId == tableNum(SalesQuotationTable)
           && docuRef.RefRecId   == salesQuotationTable.RecId
    {
        copyDocuRef.clear();
        copyDocuRef.data(docuRef);
        copyDocuRef.RefTableId = tableNum(CustQuotationJour);
        copyDocuRef.RefRecId   = custQuotationJour.RecId;
        docuRefInsertList.add(copyDocuRef);
    }

    while select docuRef order by KCS_TCVLineNum
        join  locSalesQuotationLine
            where locSalesQuotationLine.TableId == docuRef.RefTableId
               && locSalesQuotationLine.RecId   == docuRef.RefRecId
               && locSalesQuotationLine.QuotationId == salesQuotationTable.QuotationId
                 join locCustQuotationTrans
                    where locCustQuotationTrans.InventTransId == locSalesQuotationLine.InventTransId
                       && locCustQuotationTrans.QuotationId   == custQuotationJour.QuotationId
                       && locCustQuotationTrans.QuotationDate == custQuotationJour.QuotationDate
    {
        copyDocuRef.clear();
        copyDocuRef.data(docuRef);
        copyDocuRef.RefTableId = tableNum(CustQuotationTrans);
        copyDocuRef.RefRecId   = locCustQuotationTrans.RecId;
        docuRefInsertList.add(copyDocuRef);
    }

    docuRefInsertList.insertDatabase();

}

/// <summary>
/// defined from AVA
/// </summary>
void postUpdate()
{

    // salesQuotationTable.selectForUpdate(true);

    next postUpdate();
    salesQuotationTable.AVAKBVRequestTablePostUpdate();
    this.updateMasterPriceMark();
    this.updateSalesQuotationTableStatus();
    this.updateAllSpecialDiscFactor();
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_salesQuotationTable">SalesQuotationTable</param>
protected void initializeSalesQuotationTableFromDocumentStatus(SalesQuotationTable _salesQuotationTable)
{
    //AVASpecialDiscQuotation         specialDiscountQuotation = AVASpecialDiscQuotation::find(_salesQuotationTable.QuotationId);
    //AmountCur                       specialDiscountAmount1, specialDiscountAmount2, specialDiscountAmount3;

    next initializeSalesQuotationTableFromDocumentStatus(_salesQuotationTable);

    if (salesQuotationTable
        && this.parmSendMode() != KCS_SendMode::Proforma)
    {
        //CustQuotationTrans  custQuotationTrans;
        LineAmount          quotLineAmount;

        /* no simple sum up of LineAmount
        select sum(LineAmount)  from custQuotationTrans
        where custQuotationTrans.QuotationId   == custQuotationJour.QuotationId
           && custQuotationTrans.QuotationDate == custQuotationJour.QuotationDate
          && custQuotationTrans.SalesId       == custQuotationJour.SalesId;

        quotLineAmount = custQuotationTrans.LineAmount;

        SpecialDiscountAmount1     = decRound(quotLineAmount*specialDiscountQuotation.SpecialDiscountPct1/100,2);
        SpecialDiscountAmount2     = decRound((quotLineAmount - SpecialDiscountAmount1) *specialDiscountQuotation.SpecialDiscountPct2/100,2);
        SpecialDiscountAmount3     = decRound((quotLineAmount - SpecialDiscountAmount1 - SpecialDiscountAmount2) *specialDiscountQuotation.SpecialDiscountPct3/100,2);
        quotLineAmount = quotLineAmount - SpecialDiscountAmount1 - SpecialDiscountAmount2 - SpecialDiscountAmount3;
        */

        quotLineAmount = custQuotationJour.displayAVABaseAmount() - custQuotationJour.avaSpecialDiscAmount(true); // amount special discounts included

        _salesQuotationTable.AVAPosted              = NoYes::Yes;
        _salesQuotationTable.AVAPostedEnum          = AVAPostedEnum::Posted;
        _salesQuotationTable.KCS_QuotationAmount    = quotLineAmount;
    }
}

public RecordSortedList parmJournalList(RecordSortedList _journalList = journalList)
{
    journalList = _journalList;
    return journalList;
}

public CustQuotationJour parmCustQuotationJour(CustQuotationJour _custQuotationJour = this.custQuotationJour)
{
    this.custQuotationJour = _custQuotationJour;
    return this.custQuotationJour;
}

public SalesQuotationParmTable parmSalesQuotationParmTable(SalesQuotationParmTable _SalesQuotationParmTable = this.salesQuotationParmTable)
{
    this.salesQuotationParmTable = _SalesQuotationParmTable;
    return this.salesQuotationParmTable;
}

/// <summary>
/// AVA <c>avaCalcQuotationMatValue</c>
/// </summary>
/// <param name = "_quotationId">QuotationId</param>
/// <param name = "_quotationDate">TransDate</param>
/// <returns>AVAQuotationMatValue</returns>
public AVAQuotationMatValue avaCalcQuotationMatValue(
    QuotationId _quotationId,
    TransDate _quotationDate)
{
    AVAQuotationMatValue avaMatValue;

    avaMatValue = this.avaMatValueNoInt(_quotationId, _quotationDate) + this.avaMatValueFirstInt(_quotationId, _quotationDate);

    return avaMatValue;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_quotationId">QuotationId</param>
/// <param name = "_quotationDate">TransDate</param>
/// <returns>AmountCur</returns>
public AmountCur avaMatValueNoInt(
    QuotationId _quotationId,
    TransDate _quotationDate)
{
    CustQuotationTrans avaCustQuotationTrans;

    select sum(LineAmount) from avaCustQuotationTrans
        where avaCustQuotationTrans.QuotationId == _quotationId
        && avaCustQuotationTrans.QuotationDate == _quotationDate
        && avaCustQuotationTrans.KCS_QLInternalPosition == 0
        && avaCustQuotationTrans.KCS_CRMIsAlternativeLine == NoYes::No;

    return avaCustQuotationTrans.LineAmount;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_quotationId">QuotationId</param>
/// <param name = "_quotationDate">TransDate</param>
/// <returns>KCS_QLLVAmount</returns>
public KCS_QLLVAmount avaMatValueFirstInt(
    QuotationId _quotationId,
    TransDate _quotationDate)
{
    CustQuotationTrans avaCustQuotationTrans;

    select sum(KCS_QLLVAmount) from avaCustQuotationTrans
        where avaCustQuotationTrans.QuotationId == _quotationId
        && avaCustQuotationTrans.QuotationDate == _quotationDate
        && avaCustQuotationTrans.KCS_QLInternalPosition == 1
        && avaCustQuotationTrans.KCS_CRMIsAlternativeLine == NoYes::No;

    return avaCustQuotationTrans.KCS_QLLVAmount;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <returns>QueryRun</returns>
QueryRun  queryBuildSalesQuotationTable()
{
    QueryRun locQueryRun;

    this.skipQueryStatusFilter(true);

    locQueryRun = next queryBuildSalesQuotationTable();

    return locQueryRun;
}

/// <summary>
/// designed from AVA
/// </summary>
void updateMasterPriceMark()
{
    if (!salesQuotationParmUpdate.proforma)
    {
        salesQuotationLine  locSalesQuotationLine;
        update_recordset locSalesQuotationLine
        setting KCS_CalcMark = ''
        where locSalesQuotationLine.QuotationId == salesQuotationTable.QuotationId
        && locSalesQuotationLine.KCS_CalcMark == 'M';
    }
}

/// <summary>
/// designed from AVA
/// </summary>
void updateSalesQuotationTableStatus()
{
    KCS_QuotationStatus        quotationStatus;
    SalesQuotationTable        locSalesQuotationTable;
    select firstonly quotationStatus
        where quotationStatus.KCS_SalesQuotationStatus == SalesQuotationStatus::Sent;

    if (quotationStatus)
    {
        locSalesQuotationTable = SalesQuotationTable::find(salesQuotationTable.QuotationId);
        if (locSalesQuotationTable.KCS_StatusId == '0')
        {
            locSalesQuotationTable.KCS_StatusId = quotationStatus.KCS_StatusId;
            locSalesQuotationTable.selectForUpdate(true);
            locSalesQuotationTable.doUpdate();
        }
    }
}

/// <summary>
/// designed from AVA
/// </summary>
void updateAllSpecialDiscFactor()
{
    SalesQuotationTable             locSalesQuotationTable;

    AVASpecialDiscQuotationJour     specialDiscQuotationJour = AVASpecialDiscQuotationJour::findQuotation(custQuotationJour.RecId);

    locSalesQuotationTable = SalesQuotationTable::find(salesQuotationTable.QuotationId);
    locSalesQuotationTable.AVASpecialDiscFactor  = specialDiscQuotationJour.AllDiscountFactor;
    locSalesQuotationTable.selectForUpdate(true);
    locSalesQuotationTable.doUpdate();
}
